create or replace function public.get_fleet_leaderboard(p_business_id uuid,p_metric text default 'safety_score',p_target_type text default 'driver',p_limit integer default 20) returns table(rank bigint,business_id uuid,target_id uuid,target_type text,metric text,value numeric,score numeric,network_visible boolean) language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ declare v_limit integer:=greatest(1,least(coalesce(p_limit,20),100)); begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.fleet_observe_access(p_business_id) then raise exception 'Fleet access required'; end if; if lower(coalesce(p_target_type,''))='driver' then return query select row_number() over(order by coalesce(avg(s.safety_score),0) desc,s.driver_id),s.business_id,s.driver_id,'driver',lower(p_metric),case lower(p_metric) when 'safety_score' then avg(s.safety_score) when 'efficiency_score' then avg(s.efficiency_score) when 'route_completion_score' then avg(s.route_completion_score) when 'idle_minutes' then avg(s.idle_minutes) when 'harsh_braking_count' then avg(s.harsh_braking_count) when 'harsh_acceleration_count' then avg(s.harsh_acceleration_count) when 'speeding_events' then avg(s.speeding_events) when 'collision_events' then avg(s.collision_events) when 'seatbelt_events' then avg(s.seatbelt_events) else avg(s.safety_score) end,case lower(p_metric) when 'safety_score' then avg(s.safety_score) when 'efficiency_score' then avg(s.efficiency_score) when 'route_completion_score' then avg(s.route_completion_score) when 'idle_minutes' then avg(s.idle_minutes) else null end,true from public.fleet_driver_scorecards s where s.business_id=p_business_id group by s.business_id,s.driver_id order by value desc nulls last,target_id limit v_limit; elsif lower(p_target_type)='fleet' then return query select row_number() over(order by value desc nulls last,business_id),business_id,null::uuid,'fleet',lower(p_metric),value,value,true from (select f.business_id,case lower(p_metric) when 'vehicles_active' then avg(f.vehicles_active)::numeric when 'routes_completed' then sum(f.routes_completed)::numeric when 'stops_completed' then sum(f.stops_completed)::numeric when 'restroom_coverage_score' then avg(f.restroom_coverage_score)::numeric when 'average_stop_distance_miles' then avg(f.average_stop_distance_miles)::numeric when 'estimated_time_saved_minutes' then sum(f.estimated_time_saved_minutes)::numeric else sum(f.stops_completed)::numeric end value from public.fleet_metric_snapshots f where f.business_id=p_business_id group by f.business_id)x; else raise exception 'Unsupported Fleet leaderboard target type: %',p_target_type; end if; end $$;
create or replace function public.get_fleet_metric_capabilities(p_business_id uuid) returns jsonb language plpgsql stable security definer set search_path to 'public','auth','extensions','pg_temp' as $$ declare v_capabilities jsonb; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.fleet_observe_access(p_business_id) then raise exception 'Fleet access required'; end if; select coalesce(jsonb_agg(to_jsonb(x) order by x.domain,x.metric_key),'[]'::jsonb) into v_capabilities from (select 'fleet'::text domain,'fleet_routes'::text source_dataset,'routes_completed'::text metric_key,'count'::text aggregation,'route'::text natural_scope,'count'::text unit,'existing_fleet_snapshot'::text source_kind,'Route completion from fleet_metric_snapshots.'::text description,jsonb_build_array('live_network','notifications','leaderboards','progression') interoperability union all select 'fleet','fleet_metric_snapshots','stops_completed','count','fleet','count','existing_fleet_snapshot','Completed stops from fleet_metric_snapshots.',jsonb_build_array('live_network','notifications','feedback','routing') union all select 'fleet','fleet_metric_snapshots','vehicles_active','count','fleet','count','existing_fleet_snapshot','Active vehicles from fleet_metric_snapshots.',jsonb_build_array('live_network','notifications') union all select 'fleet','fleet_metric_snapshots','restroom_coverage_score','avg','fleet','score','existing_fleet_snapshot','Restroom coverage score from fleet_metric_snapshots.',jsonb_build_array('quality','feedback','notifications','progression') union all select 'fleet','fleet_metric_snapshots','average_stop_distance_miles','avg','fleet','miles','existing_fleet_snapshot','Average stop distance from fleet_metric_snapshots.',jsonb_build_array('routing','live_network','notifications') union all select 'fleet','fleet_metric_snapshots','estimated_time_saved_minutes','sum','fleet','minutes','existing_fleet_snapshot','Estimated time saved from fleet_metric_snapshots.',jsonb_build_array('routing','notifications','leaderboards') union all select 'fleet','fleet_driver_scorecards','safety_score','avg','driver','score','existing_fleet_scorecard','Driver safety score from fleet_driver_scorecards.',jsonb_build_array('progression','leaderboards','notifications') union all select 'fleet','fleet_driver_scorecards','efficiency_score','avg','driver','score','existing_fleet_scorecard','Driver efficiency score from fleet_driver_scorecards.',jsonb_build_array('progression','leaderboards','notifications') union all select 'fleet','fleet_driver_scorecards','route_completion_score','avg','driver','score','existing_fleet_scorecard','Driver route completion score from fleet_driver_scorecards.',jsonb_build_array('routing','progression','leaderboards','notifications') union all select 'fleet','fleet_driver_scorecards','idle_minutes','sum','driver','minutes','existing_fleet_scorecard','Driver idle minutes from fleet_driver_scorecards.',jsonb_build_array('routing','notifications','leaderboards') union all select 'fleet','fleet_driver_scorecards','speeding_events','sum','driver','events','existing_fleet_scorecard','Driver speeding events from fleet_driver_scorecards.',jsonb_build_array('progression','notifications','leaderboards') union all select 'fleet','fleet_driver_scorecards','collision_events','sum','driver','events','existing_fleet_scorecard','Driver collision events from fleet_driver_scorecards.',jsonb_build_array('notifications','progression','leaderboards') union all select 'fleet','fleet_driver_scorecards','seatbelt_events','sum','driver','events','existing_fleet_scorecard','Driver seatbelt events from fleet_driver_scorecards.',jsonb_build_array('progression','notifications') union all select 'fleet','fleet_performance_events','metrics','latest','route','json','fleet_performance_event','Raw performance metrics payload for route/vehicle/driver operational facts.',jsonb_build_array('live_network','routing','notifications','feedback') union all select 'fleet','fleet_operational_events','value','sum','fleet','numeric','fleet_operational_event','Canonical operational event value/unit stream.',jsonb_build_array('live_network','notifications','progression','leaderboards') union all select 'network','live_network_events','event_count','count','location','events','live_network_event','Live activity/event volume associated with Fleet operations.',jsonb_build_array('intelligence','notifications','routing','feedback') union all select 'quality','location_quality_observations','quality_signals','avg','location','score','quality_observation','User-submitted location quality evidence.',jsonb_build_array('feedback','intelligence','notifications','routing') union all select 'routing','route_events','event_count','count','route','events','route_event','Canonical route lifecycle/event volume.',jsonb_build_array('live_network','notifications','offline','feedback') union all select 'routing','route_stops','stop_count','count','route','stops','route_stop','Canonical route stop population.',jsonb_build_array('live_network','notifications','feedback','offline') union all select 'feedback','user_feedback','feedback_count','count','business','events','user_feedback','User feedback volume available for operational feedback loops.',jsonb_build_array('quality','intelligence','notifications') union all select 'feedback','review_amenity_feedback','amenity_feedback_count','count','location','events','review_feedback','Review amenity feedback volume.',jsonb_build_array('quality','intelligence','notifications') union all select 'enterprise','enterprise_partner_network_metrics','network_metrics','latest','network','json','enterprise_network_metric','Existing enterprise partner network analytics.',jsonb_build_array('live_network','leaderboards','notifications')) x; return jsonb_build_object('business_id',p_business_id,'measurement_sources',v_capabilities,'shared_primitives',jsonb_build_array('progression_metric_events','progression_challenges','progression_games','business_metric_leaderboards','notification_events','live_network_events'),'rule','Fleet metric definitions reference these existing capabilities; they do not replace their source-of-truth semantics.'); end $$;
create or replace function public.get_fleet_network_leaderboard(p_metric text default 'stops_completed',p_limit integer default 20) returns table(rank bigint,business_id uuid,business_name text,metric text,value numeric,network_contribution numeric,reward jsonb) language sql security definer set search_path to 'public','auth','extensions','pg_catalog' as $$ with actor_businesses as (select bm.business_id from public.business_members bm where bm.user_id=auth.uid() union select b.id from public.businesses b where public.is_platform_owner(auth.uid())),fleets as (select f.business_id,b.name,case lower(p_metric) when 'vehicles_active' then avg(f.vehicles_active)::numeric when 'routes_completed' then sum(f.routes_completed)::numeric when 'stops_completed' then sum(f.stops_completed)::numeric when 'restroom_coverage_score' then avg(f.restroom_coverage_score)::numeric when 'average_stop_distance_miles' then avg(f.average_stop_distance_miles)::numeric when 'estimated_time_saved_minutes' then sum(f.estimated_time_saved_minutes)::numeric else sum(f.stops_completed)::numeric end value from public.fleet_metric_snapshots f join public.businesses b on b.id=f.business_id where coalesce(b.is_demo_test,false)=false and exists(select 1 from actor_businesses ab where ab.business_id=f.business_id) and public.fleet_observe_access(f.business_id) group by f.business_id,b.name),ranked as (select row_number() over(order by value desc nulls last,business_id) r,business_id,name,value from fleets) select r.r,r.business_id,r.name,lower(p_metric),r.value,case when max(r.value) over()>0 then round((r.value/nullif(max(r.value) over(),0))*100,2) else 0 end,(select coalesce(jsonb_agg(to_jsonb(lr) order by lr.rank_from desc),'[]'::jsonb) from public.leaderboard_rewards lr where lr.active and lr.leaderboard_key='fleet_network:'||lower(p_metric) and r.r between lr.rank_from and lr.rank_to) from ranked r where public.fleet_observe_access(r.business_id) order by r.r limit greatest(1,least(coalesce(p_limit,20),100)); $$;
